constexpr int searchValueToStoredValue(Value value, int searchPly)
{
    return value == VALUE_NONE               ? VALUE_NONE
           : value >= VALUE_MATE_IN_MAX_PLY  ? value + searchPly
           : value <= VALUE_MATED_IN_MAX_PLY ? value - searchPly
                                             : value;
}
