{
    return storedValue == VALUE_NONE               ? VALUE_NONE
           : storedValue >= VALUE_MATE_IN_MAX_PLY  ? Value(storedValue - searchPly)
           : storedValue <= VALUE_MATED_IN_MAX_PLY ? Value(storedValue + searchPly)
                                                   : Value(storedValue);
}
