#include <cstdint>
template <typename ElemType, int Size>
constexpr int arraySize(ElemType (&)[Size])
{
    return Size;
}
template <class T>
constexpr T power(T base, unsigned exponent)
{
    T result = 1;
    while (exponent > 0) {
        if (exponent & 1u)
            result *= base;
        base *= base;
        exponent >>= 1;
    }
    return result;
}
constexpr bool isPowerOfTwo(uint64_t x)
{
    return (x & (x - 1)) == 0;
}
constexpr uint64_t floorLog2(uint64_t x)
{
    return x == 1 ? 0 : 1 + floorLog2(x >> 1);
}
constexpr uint64_t ceilLog2(uint64_t x)
{
    return floorLog2(x) + !isPowerOfTwo(x);
}
constexpr uint32_t combineNumber(uint32_t n, uint32_t m)
{
    uint64_t r = 1;
    for (unsigned int i = n; i < m + n; i++)
        r *= i;
    for (unsigned int i = 2; i <= m; i++)
        r /= i;
    return (uint32_t)r;
}
#include <algorithm>
#include <array>
